const nexusNote={"Alaska":"Solo impuestos locales sobre ventas, a través de la Alaska Remote Seller Sales Tax Commission","Illinois":"Se eliminó la prueba de transacciones el 1 de enero de 2026","Kentucky":"Se eliminó la prueba de transacciones el 1 de agosto de 2026"};

/* ---------- Checklist (same ids as the English items) ---------- */
const PHASE={"Step 1":"Obtenga ayuda gratuita","Step 2":"Dé forma a la idea","Step 3":"Hágalo oficial","Step 4":"Licencias, permisos e impuestos","Step 5":"Proteja su dinero","Step 6":"Lance y dése a conocer"};
const ITEMS={
  "help-sbdc":c=>["Reserve una sesión gratuita con su Small Business Development Center (SBDC, centro de desarrollo de pequeñas empresas)",`Los asesores en ${c.st} ayudan con la planificación, el presupuesto, el registro y la búsqueda de financiamiento. ${c.L("Encuentre su SBDC","https://americassbdc.org")}`],
  "help-score":c=>["Solicite un mentor gratuito de SCORE",`Pida un mentor con experiencia en ${c.sh}. ${c.L("Encuentre un mentor","https://www.score.org/find-mentor")}`],
  "help-local":c=>[`Pregunte a la oficina de desarrollo económico y a la cámara de comercio de ${c.city||"su ciudad"} por programas locales`,"Las subvenciones locales, los micropréstamos, los talleres gratuitos y los espacios compartidos suelen anunciarse allí primero."],
  "help-lib":c=>[`Use los recursos para negocios de la biblioteca pública${c.city?" de "+c.city:""}`,"Bases de datos gratuitas de investigación de mercado, guías de planes de negocio y, a menudo, salas de reunión gratuitas."],
  "ok-ocn":c=>["Llame a OCN e i2E: pregunte qué programa abierto conviene a un fundador de tecnología sin ingresos "+tgs("Oklahoma"),"Luego hable con Gradient y Build in Tulsa. Vea “Ayuda según su negocio”."],
  "tul-aj":c=>["Pregunte a Avanzando Juntos por microsubvenciones y ayuda con los costos de formación "+tgs("Tulsa"),"Teléfono 918-212-0750. Hay que confirmar la disponibilidad y los requisitos."],
  "dal-sbdc":c=>["Solicite asesoría sin costo al Dallas Metropolitan SBDC "+tgs("Dallas"),"Atiende los condados de Dallas, Collin y Rockwall; teléfono 214-860-5848. En el condado de Tarrant (Arlington), use el Tarrant SBDC. Vea “Ayuda según su negocio”."],
  "idea-desc":c=>["Escriba un párrafo que describa qué vende y a quién","Lo usará en cada carta, solicitud y formulario bancario."],
  "idea-cust":c=>["Hable con al menos diez posibles clientes antes de gastar dinero","Pregunte por su problema y cuánto pagan hoy, no si les gusta su idea."],
  "idea-price":c=>["Fije un precio inicial a partir de los costos reales y de lo que pagan hoy los clientes","Incluya su tiempo, materiales, tarifas e impuestos. Es más fácil dar descuentos que subir precios."],
  "idea-budget":c=>["Haga una lista de lo que necesita para empezar y de lo que puede esperar","Separe lo indispensable de lo que sería bueno tener. Su asesor puede revisarla."],
  "idea-plan":c=>["Esboce un plan de negocio de una página",c.L("Guía de la SBA para el plan de negocio",c.SBA+"plan-your-business/write-your-business-plan")],
  "idea-mvp":c=>["Defina la versión más pequeña que resuelve el problema principal "+tgs("Software"),"Construya solo lo que un cliente piloto necesita para ver el valor. Consiga de 3 a 5 usuarios piloto antes de construir más. Vea “Darse a conocer”."],
  "reg-structure":c=>["Elija una estructura: sole proprietorship (empresa individual), partnership (sociedad), LLC o corporation (corporación)","Vea “Estructuras”. Puede empezar con algo sencillo y cambiar después."],
  "reg-name":c=>["Verifique el nombre de su negocio",`Busque en la base de datos de nombres de negocios de ${c.st} y en la base de datos federal de marcas. ${c.L("Búsqueda en la USPTO","https://www.uspto.gov/trademarks/search")}`],
  "reg-file":c=>{const d=c.d;if(!d)return [`Regístrese en ${c.st} si forma una LLC o corporación`,"Elija su estado arriba para ver aquí sus tarifas y reglas. Detalles en “LLC por estado”."];
    const x=c.llcText(c.S.state);return [`Regístrese en ${c.st} si forma una LLC o corporación`,`${c.state}: ${c.docName(c.S.state)}, tarifa de presentación ${c.money(d[0])}; continuo: ${x[0]} (${c.ongoing(d)}).${x[2]?" "+x[2]:""} Detalles en “LLC por estado”.`]},
  "reg-dba":c=>["Registre un DBA (nombre comercial) si operará con otro nombre",c.S.state==="Texas"?"Texas: los sole proprietors y las sociedades generales presentan un assumed name certificate (certificado de nombre supuesto) ante el secretario del condado (county clerk); las LLC y corporaciones lo presentan ante el Secretary of State ($25). "+c.L("Texas SOS: registros de nombres","https://www.sos.state.tx.us/corp/namefilingsfaqs.shtml"):"Se registra ante el estado o el condado, según donde viva."],
  "reg-ein":c=>["Obtenga un EIN gratuito del IRS",`Solicítelo solo en irs.gov; nunca le pague a un tercero por él. ${c.L("Solicitar un EIN","https://www.irs.gov/businesses/small-businesses-self-employed/get-an-employer-identification-number")}`],
  "reg-oa":c=>["Firme un operating agreement (acuerdo operativo) o un acuerdo de sociedad","Define la propiedad, las decisiones, el dinero y qué pasa si alguien se va. Es esencial con más de un dueño."],
  "tx-franchise":c=>["Haga cada año su presentación del Texas franchise tax (impuesto de franquicia) antes del 15 de mayo "+tgs("Texas"),`Toda LLC (y toda otra entidad sujeta al impuesto; no los sole proprietors) presenta cada año. En o por debajo del umbral sin impuesto a pagar ($2.65 millones para los informes de 2026 y 2027), presente solo el Public Information Report (informe de información pública) u Ownership Information Report (informe de propiedad); el No Tax Due Report ya no se presenta. Por encima del umbral, presente el informe del franchise tax. ${c.L("Comptroller: franchise tax","https://comptroller.texas.gov/taxes/franchise/")} · ${c.L("Reportes sin impuesto a pagar","https://comptroller.texas.gov/taxes/franchise/ntd-rpt-updates-2024.php")}`],
  "lic-local":c=>[`Pregunte a ${c.city||"su ciudad"} y a su condado qué licencia comercial o permisos aplican`,`Los requisitos dependen de su actividad y dirección. ${c.L("SBA: licencias y permisos",c.SBA+"launch-your-business/apply-licenses-permits")}`],
  "lic-statetax":c=>[`Regístrese para los impuestos de ${c.st} que le apliquen`,`${c.S.state&&c.NEXUS[c.S.state]===null?c.state+" no tiene impuesto estatal sobre ventas, pero pueden aplicar otros impuestos estatales. ":""}El departamento de ingresos de su estado administra los impuestos sobre la renta, las ventas y otros impuestos comerciales. ${c.L("SBA: números de identificación fiscal",c.SBA+"launch-your-business/get-federal-state-tax-id-numbers")}`],
  "tx-sales":c=>["Obtenga un sales and use tax permit (permiso de impuesto sobre ventas y uso) de Texas si vende bienes o servicios gravables "+tgs("Texas"),`Es obligatorio si vende o arrienda bienes muebles tangibles en Texas o vende servicios gravables allí. Solicítelo en línea por eSystems del Comptroller antes de su primera venta gravable. ${c.L("Comptroller: permiso de impuesto sobre ventas","https://comptroller.texas.gov/taxes/permit/")}`],
  "sw-pay":c=>["Decida cómo cobrará y quién se encarga del impuesto sobre ventas "+tgs("Software"),"Compras dentro de la app en tiendas de aplicaciones: Apple y Google cobran y pagan por usted el impuesto sobre ventas de EE. UU., pero se quedan con una comisión. Facturación directa por la web: usted se encarga del impuesto, o usa un servicio merchant of record (como Paddle) que lo haga. El SaaS está gravado en algunos estados y en otros no."],
  "sw-legal":c=>["Publique una política de privacidad y términos de servicio "+tgs("Software"),`Lo exigen las tiendas de aplicaciones y los procesadores de pago, y las leyes estatales de privacidad a medida que crece. Si su aplicación está dirigida a menores de 13 años, aplica COPPA. ${c.L("FTC: privacidad infantil","https://www.ftc.gov/business-guidance/privacy-security/childrens-privacy")}`],
  "sw-ip":c=>["Obtenga una cesión de propiedad intelectual por escrito de quien programe o diseñe para usted "+tgs("Software"),"Sin ella, los contratistas pueden conservar los derechos de autor de lo que construyen. También lleve control de las licencias de los paquetes de código abierto que use."],
  "sw-reg":c=>["Verifique si su aplicación está en una categoría regulada "+tgs("Software"),"Las aplicaciones que mueven dinero, prestan, aseguran, dan atención médica, corretean bienes raíces, ofrecen apuestas o sorteos pagados, o entregan alcohol suelen necesitar licencias en cada estado donde están los usuarios. Vea “Vender en otros estados”."],
  "sw-access":c=>["Diseñe con accesibilidad (WCAG) desde el principio "+tgs("Software"),"Las aplicaciones accesibles llegan a más usuarios y reducen el riesgo de quejas bajo la ADA. Corregirlo después cuesta mucho más."],
  "sw-sec":c=>["Proteja los datos de los usuarios: cifrado, control de acceso y un plan ante filtraciones "+tgs("Software"),`Todos los estados tienen una ley de notificación de filtraciones de datos. ${c.L("FTC: seguridad de datos","https://www.ftc.gov/business-guidance/privacy-security/data-security")}`],
  "ec-permit":c=>["Obtenga un seller's permit (permiso de vendedor) en su estado antes de su primera venta gravable "+tgs("Comercio electrónico"),"Mercados como Amazon, Etsy y eBay cobran el impuesto sobre ventas por usted en sus ventas. Su propio sitio web no lo hace."],
  "ec-ship":c=>["Publique sus políticas de envío, devoluciones y reembolsos "+tgs("Comercio electrónico"),`La Mail Order Rule de la FTC exige enviar en el plazo que usted indique, o dentro de 30 días si no indica ninguno. ${c.L("FTC: Mail Order Rule","https://www.ftc.gov/business-guidance/resources/business-guide-ftcs-mail-internet-or-telephone-order-merchandise-rule")}`],
  "ec-safety":c=>["Revise las reglas de seguridad de los productos que vende "+tgs("Comercio electrónico"),`Los productos para niños necesitan pruebas de un tercero y un Children's Product Certificate (certificado de producto infantil). Vender a California puede requerir advertencias de la Prop 65. ${c.L("Guía de la CPSC para negocios","https://www.cpsc.gov/Business--Manufacturing")}`],
  "ec-privacy":c=>["Publique una política de privacidad y use un pago seguro "+tgs("Comercio electrónico"),"Use un procesador de pagos que cumpla con PCI; nunca guarde números de tarjeta usted mismo."],
  "sv-lic":c=>[`Verifique si su profesión requiere licencia en ${c.st} `+tgs("Servicios"),`Contabilidad, derecho, bienes raíces, ingeniería, seguros, asesoría financiera y muchas otras necesitan una licencia estatal. ${c.L("Buscador de ocupaciones con licencia",c.LIC)}`],
  "sv-contract":c=>["Use un contrato escrito o una descripción del trabajo con cada cliente "+tgs("Servicios"),"Alcance, precio, condiciones de pago, quién es dueño del trabajo y cómo puede terminarlo cualquiera de las partes."],
  "sv-eo":c=>["Pregunte por un seguro de responsabilidad profesional (E&O) "+tgs("Servicios"),"Cubre reclamos de que su asesoría o trabajo le causó una pérdida a un cliente. Algunos clientes lo exigen."],
  "rt-permit":c=>["Obtenga un seller's permit (permiso de vendedor) y un resale certificate (certificado de reventa) "+tgs("Comercio minorista"),"El permiso le permite cobrar el impuesto sobre ventas; el certificado de reventa le permite comprar inventario para revender sin pagar impuesto sobre ventas."],
  "rt-coo":c=>["Confirme la zonificación, el certificate of occupancy (certificado de ocupación), la inspección de bomberos y los permisos de letreros "+tgs("Comercio minorista"),"Verifíquelo antes de firmar un contrato de arrendamiento. Arreglar un problema de zonificación después de firmar sale caro."],
  "rt-ins":c=>["Obtenga seguro de responsabilidad general y de productos "+tgs("Comercio minorista"),"Los arrendadores suelen exigir responsabilidad general. La de productos importa si fabrica, importa o vende productos con su propia marca."],
  "rt-safety":c=>["Revise las reglas de seguridad de los productos que vende "+tgs("Comercio minorista"),c.L("Guía de la CPSC para negocios","https://www.cpsc.gov/Business--Manufacturing")],
  "fd-health":c=>["Consulte al departamento de salud local sobre los permisos "+tgs("Alimentos"),"Restaurantes, food trucks, servicios de banquetes y puestos necesitan un permiso de establecimiento de alimentos o de venta ambulante, e inspecciones."],
  "fd-cottage":c=>[`Revise la ley de cottage food (alimentos caseros) de ${c.st} si cocinará en casa `+tgs("Alimentos"),"La mayoría de los estados permite vender algunos alimentos de bajo riesgo hechos en casa, con límites en los productos, las ventas y dónde se venden. Por lo general no se pueden enviar a otros estados."],
  "fd-cert":c=>["Obtenga una certificación de seguridad alimentaria "+tgs("Alimentos"),"La mayoría de las jurisdicciones exige un gerente certificado en protección de alimentos y tarjetas de manipulador de alimentos para el personal."],
  "fd-kitchen":c=>["Consiga una cocina comercial o comisariato con licencia si la necesita "+tgs("Alimentos"),"Se exige para la mayoría de los food trucks y para alimentos fuera de las reglas de cottage food."],
  "fd-label":c=>["Etiquete correctamente los alimentos empacados "+tgs("Alimentos"),`Ingredientes, alérgenos, cantidad neta y el nombre y dirección de su negocio. Los pequeños negocios pueden estar exentos de la información nutricional. ${c.L("FDA: etiquetado","https://www.fda.gov/food/food-labeling-nutrition")}`],
  "fd-alc":c=>["¿Venderá alcohol? Empiece por la licencia estatal de bebidas alcohólicas "+tgs("Alimentos"),"El alcohol requiere una licencia estatal, a menudo una local, y permisos federales del TTB si lo produce."],
  "tr-lic":c=>["Obtenga su licencia de contratista u oficio "+tgs("Oficios"),`Muchos estados y ciudades otorgan licencias a contratistas generales y a oficios como electricidad, plomería y HVAC. ${c.L("Buscador de ocupaciones con licencia",c.LIC)}`],
  "tr-bond":c=>["Obtenga una fianza y un seguro "+tgs("Oficios"),"Responsabilidad general y, a menudo, una fianza (surety bond) para la licencia. Workers' comp (compensación laboral) cuando tenga empleados."],
  "tr-permit":c=>["Saque los permisos de construcción de cada obra "+tgs("Oficios"),"Por lo general en el departamento de construcción de la ciudad o el condado."],
  "tr-lead":c=>["¿Trabaja en casas construidas antes de 1978? Obtenga la certificación de la EPA para trabajo seguro con plomo (RRP) "+tgs("Oficios"),`Se exige para renovaciones, reparaciones y pintura que alteren la pintura en casas anteriores a 1978 y en instalaciones con niños. ${c.L("Programa RRP de la EPA","https://www.epa.gov/lead/renovation-repair-and-painting-program")}`],
  "tr-osha":c=>["Siga las reglas de seguridad de OSHA "+tgs("Oficios"),c.L("OSHA para pequeños negocios","https://www.osha.gov/smallbusiness")],
  "hm-lic":c=>["Obtenga una licencia comercial local "+tgs("Servicios del hogar"),"La mayoría de las ciudades y condados la exigen para servicios de limpieza, jardinería y mantenimiento."],
  "hm-ins":c=>["Obtenga seguro de responsabilidad general y considere una fianza de limpieza "+tgs("Servicios del hogar"),"Los clientes suelen pedir comprobante. Una fianza cubre reclamos por robo contra los trabajadores."],
  "hm-pest":c=>["¿Aplica pesticidas o herbicidas para clientes? Obtenga la licencia "+tgs("Servicios del hogar"),"La mayoría de los estados exige una licencia de aplicador comercial del departamento estatal de agricultura, incluso para el control de maleza en céspedes."],
  "hm-auto":c=>["Asegure su vehículo para uso comercial "+tgs("Servicios del hogar"),"Las pólizas de auto personales a menudo excluyen el uso comercial."],
  "ca-lic":c=>["Obtenga su licencia profesional estatal "+tgs("Cuidado personal"),`Cosmetología, barbería, masaje, enfermería y muchas profesiones de salud necesitan una licencia de la junta estatal. ${c.L("Buscador de ocupaciones con licencia",c.LIC)}`],
  "ca-shop":c=>["Obtenga licencia para su local si se requiere "+tgs("Cuidado personal"),"Salones, spas y clínicas a menudo necesitan una licencia de establecimiento aparte de su licencia personal."],
  "ca-hipaa":c=>["¿Maneja información de salud de pacientes? Cumpla con HIPAA "+tgs("Cuidado personal"),c.L("HHS: HIPAA para profesionales","https://www.hhs.gov/hipaa/for-professionals/index.html")],
  "ca-ins":c=>["Obtenga seguro de responsabilidad profesional y exenciones firmadas por los clientes "+tgs("Cuidado personal"),"Los negocios de ejercicio y bienestar suelen usar exenciones firmadas y formularios de admisión."],
  "ch-lic":c=>[`Contacte a la agencia de licencias de cuidado infantil de ${c.st} `+tgs("Cuidado infantil"),`El cuidado infantil necesita una licencia estatal o una exención específica, incluso en su casa. ${c.L("Childcare.gov: recursos por estado","https://childcare.gov/state-resources")}`],
  "ch-bg":c=>["Complete la verificación de antecedentes para usted y para cualquier persona cerca de los niños "+tgs("Cuidado infantil"),"Los estados suelen exigir verificaciones con huellas digitales y búsquedas en registros."],
  "ch-train":c=>["Obtenga certificación en RCP, primeros auxilios y la capacitación requerida "+tgs("Cuidado infantil"),"Además de la capacitación en salud y seguridad que fije su estado."],
  "ch-ins":c=>["Obtenga un seguro de responsabilidad para cuidado infantil "+tgs("Cuidado infantil"),"Las pólizas de vivienda casi nunca cubren una guardería en casa."],
  "ch-food":c=>["Pregunte por el programa de alimentos del USDA (CACFP) "+tgs("Cuidado infantil"),"Puede reembolsar a proveedores elegibles por comidas y meriendas saludables."],
  "tp-ins":c=>["Obtenga un seguro de auto comercial "+tgs("Transporte"),"Las pólizas personales suelen excluir las entregas y los acarreos pagados."],
  "tp-dot":c=>["Revise las reglas federales del USDOT y de autoridad operativa "+tgs("Transporte"),`Los vehículos comerciales que cruzan estados suelen necesitar un número USDOT; los transportistas interestatales por contrato también necesitan operating authority (autoridad operativa). ${c.L("Registro en la FMCSA","https://www.fmcsa.dot.gov/registration")}`],
  "tp-cdl":c=>["Confirme si los conductores necesitan una CDL (licencia de conducir comercial) "+tgs("Transporte"),"Por lo general se exige para vehículos de más de 26,000 libras, materiales peligrosos o vehículos de pasajeros más grandes."],
  "tp-move":c=>["¿Muda artículos del hogar? Revise las licencias estatales de mudanza "+tgs("Transporte"),"Muchos estados otorgan licencias a las mudanzas dentro del estado aparte de las reglas federales."],
  "cr-copy":c=>["Registre los derechos de autor de sus obras principales "+tgs("Creativo"),`El registro es necesario antes de poder demandar por infracción. ${c.L("U.S. Copyright Office","https://www.copyright.gov/registration/")}`],
  "cr-music":c=>["Obtenga licencia para la música que pone en eventos o en su negocio "+tgs("Creativo"),"Las licencias de ejecución pública las otorgan ASCAP, BMI, SESAC y GMR."],
  "cr-release":c=>["Use autorizaciones de modelos y de propiedad "+tgs("Creativo"),"Se necesitan antes de usar la imagen de una persona o una propiedad privada en trabajo comercial."],
  "cr-event":c=>["Revise los permisos de eventos y de ventas temporales "+tgs("Creativo"),"Los festivales y ferias de artesanía pueden requerir un permiso de evento temporal y una licencia temporal de impuesto sobre ventas."],
  "ot-lic":c=>["Verifique si su actividad necesita una licencia estatal "+tgs("General"),c.L("Buscador de ocupaciones con licencia",c.LIC)],
  "lic-home":c=>["Revise la zonificación y las reglas de su contrato de alquiler o de la HOA para un negocio en casa "+tgs("Desde casa"),"Muchas ciudades exigen un permiso de ocupación en el hogar, sobre todo si vienen clientes o guarda inventario."],
  "lic-site":c=>["Confirme la zonificación y el certificate of occupancy (certificado de ocupación) antes de firmar un arrendamiento "+tgs("Local"),"Pregunte a la ciudad si el espacio está zonificado para su uso."],
  "lic-mobile":c=>["Revise las licencias en cada ciudad donde trabajará "+tgs("Móvil"),"Algunas ciudades exigen su propia licencia comercial aunque su base esté en otro lugar."],
  "lic-multi":c=>["Revise las reglas para vender en varios estados "+tgs("Varios estados"),"Umbrales del impuesto sobre ventas, registro como entidad extranjera y actividades reguladas. Vea “Vender en otros estados”."],
  "hire-1":c=>["Configure la retención de nómina y el reporte de nuevos empleados de su estado "+tgs("Contratación"),c.L("SBA: contratar y administrar empleados",c.SBA+"manage-your-business/hire-manage-employees")],
  "hire-2":c=>[`Regístrese en el seguro de desempleo de ${c.st} y obtenga workers' comp (compensación laboral) `+tgs("Contratación"),c.S.state==="Texas"?"Texas hace opcional la compensación laboral para la mayoría de los empleadores privados, pero no tenerla implica un riesgo real. Consulte a un asesor.":"La mayoría de los estados exige compensación laboral cuando tiene empleados. Las reglas varían según el estado y el número de empleados."],
  "tx-twc":c=>["Regístrese con la Texas Workforce Commission dentro de 10 días de quedar sujeto al impuesto de desempleo "+tgs("Texas"),`La mayoría de los empleadores se registra en línea por el sistema Unemployment Tax Registration (UTR) de la TWC. ${c.L("TWC: registrar una cuenta fiscal","https://www.twc.texas.gov/services/register-tax")}`],
  "tx-newhire":c=>["Reporte cada nuevo empleado al Texas Attorney General dentro de 20 días "+tgs("Texas"),`En Texas, los reportes de nuevos empleados van a la División de Manutención Infantil (Child Support Division) del Attorney General. ${c.L("Reporte de nuevos empleados en Texas","https://www.texasattorneygeneral.gov/child-support/employers/new-hire-reporting")}`],
  "hire-3":c=>["Complete el Form I-9 de cada nuevo empleado "+tgs("Contratación"),"Verifica la identidad y la autorización para trabajar. Guarde los formularios en archivo."],
  "hire-4":c=>["Clasifique correctamente a los trabajadores "+tgs("Contratación"),`Tratar a un empleado como contratista puede generar impuestos atrasados y multas. ${c.L("IRS: ¿contratista o empleado?","https://www.irs.gov/businesses/small-businesses-self-employed/independent-contractor-self-employed-or-employee")}`],
  "money-bank":c=>["Abra una cuenta bancaria separada para el negocio",c.L("SBA: cuentas bancarias del negocio",c.SBA+"launch-your-business/open-business-bank-account")],
  "money-books":c=>["Elija una forma sencilla de registrar ingresos y gastos","Una hoja de cálculo o una aplicación gratuita basta para empezar. Guarde todos los recibos."],
  "money-tax":c=>["Aparte dinero para impuestos y conozca las fechas de los impuestos estimados","Los dueños que trabajan por cuenta propia suelen pagar impuestos federales estimados cada trimestre. Muchos apartan entre 25 y 30% de la ganancia hasta conocer su tasa."],
  "money-ins":c=>["Pregunte por el seguro que necesita su trabajo",`La responsabilidad general es común. ${["trades","transport","home"].includes(c.t)?"Puede necesitar auto comercial y fianza. ":""}${c.w==="home"?"Las pólizas de vivienda normalmente no cubren la actividad del negocio. ":""}${c.L("SBA: seguros para negocios",c.SBA+"launch-your-business/get-business-insurance")}`],
  "money-contract":c=>["Use acuerdos escritos con clientes y socios","Una clínica legal gratuita o un mentor de SCORE puede revisar una plantilla sencilla."],
  "launch-pilot":c=>[c.t==="software"||c.t==="services"?"Haga una prueba piloto con 3 a 5 clientes objetivo":"Consiga sus primeros clientes que paguen","Use la guía en “Darse a conocer”. El generador de cartas tiene una propuesta de prueba piloto y una carta de intención."],
  "launch-profile":c=>c.w==="online"?["Aparezca donde buscan sus clientes","Los negocios solo en línea no califican para un Google Business Profile; use directorios, mercados y tiendas de aplicaciones de su sector."]:["Reclame su Google Business Profile gratuito","Lo muestra en Google Search y Maps sin costo. Los negocios que atienden por zona pueden ocultar su dirección."],
  "launch-reviews":c=>["Pida a sus clientes satisfechos reseñas honestas","Nunca compre, invente ni filtre reseñas; la FTC multa a los negocios que lo hacen."],
  "launch-cal":c=>["Anote las fechas límite recurrentes en su calendario","Declaraciones de impuestos, renovaciones de licencias y el informe anual de su estado si formó una LLC o corporación."],
  "launch-apply":c=>["Solicite programas que le convengan y estén abiertos ahora","Use las preguntas en “Financiamiento” para verificar si le conviene antes de solicitar."]
};
function phases(P,ctx){
  const S=ctx.S;
  /* City and state are escaped once here; item labels are markup */
  const c={S,st:S.state?esc(S.state):"su estado",state:esc(S.state||""),city:esc(S.city||""),t:S.type,w:S.where,sh:SHORT[S.type],L:ctx.L,LIC:ctx.LIC,SBA:ctx.SBA,NEXUS:ctx.NEXUS,money:ctx.money,
    d:S.state&&ctx.LLC[S.state],docName:ctx.docName,llcText:ctx.llcText,ongoing:ctx.ongoing};
  return P.map((p,i)=>({n:p.n,label:"Paso "+(i+1),t:PHASE[p.n]||p.t,items:p.items.map(it=>{const f=ITEMS[it[0]];if(!f)return it;const x=f(c);return [it[0],x[0],x[1]]})}));
}

/* ---------- Resources (keyed by the English name, which stays as the card title) ---------- */
const res={
  "Small Business Development Centers":{who:"Socio de recursos de la SBA · casi 1,000 sedes",d:"Asesoría individual gratuita sobre planificación, presupuesto, registro y financiamiento. Muchos tienen especialistas en tecnología, exportación o contratos con el gobierno."},
  "SCORE":{who:"Mentores voluntarios en todo el país",d:"Mentoría gratuita de dueños con experiencia. Puede pedir un mentor con experiencia en su industria."},
  "Women's Business Centers":{who:"Socio de recursos de la SBA",d:"Capacitación y asesoría, a menudo con opciones por la noche y en línea. Muchos atienden a todo emprendedor, no solo a mujeres."},
  "Veterans Business Outreach Centers":{who:"Veteranos, miembros del servicio y cónyuges de militares",d:"Capacitación y asesoría empresarial, y el programa Boots to Business."},
  "Minority Business Development Agency":{who:"Departamento de Comercio de EE. UU.",d:"Centros de negocios que ayudan a empresas de minorías con crecimiento, contratos y capital."},
  "Free legal help":{who:"Ayuda legal y clínicas de facultades de derecho",d:"Grupos de ayuda legal y muchas clínicas de facultades de derecho ayudan con preguntas de formación, contratos y referencias para quienes califican."},
  "USDA Rural Development":{who:"Para zonas rurales",d:"Préstamos, subvenciones y garantías para negocios y cooperativas en comunidades rurales elegibles."},
  "Licensed occupations finder":{who:"Departamento de Trabajo de EE. UU. · CareerOneStop",d:"Busque las licencias que necesita su ocupación en su estado, con la agencia que emite cada una."},
  "SBIR / STTR programs":{who:"Fondos federales de I+D para pequeños negocios",d:"Las agencias federales financian tecnología basada en investigación mediante premios competitivos. Solo conviene si su producto implica riesgo técnico real o investigación, no una aplicación común."},
  "CodeLaunch":{who:"Competencia de startups de software",d:"Competencia y evento tipo aceleradora que ha unido a fundadores seleccionados con equipos de desarrollo, mentores e inversionistas. Útil si también necesita ayuda para construir un MVP (producto mínimo viable).",tip:"Confirme los eventos actuales, los requisitos, los costos y cualquier límite geográfico."},
  "Techstars":{who:"Red selectiva de aceleradoras",d:"Mentoría y acceso a inversionistas para startups que pueden mostrar demanda y un camino para crecer. Las condiciones pueden incluir inversión a cambio de participación."},
  "Consumer Product Safety Commission":{who:"Reglas federales de seguridad de productos",d:"Reglas de pruebas y certificados para productos de consumo, sobre todo para niños, y un defensor de pequeños negocios al que puede contactar."},
  "FDA food guidance":{who:"Reglas federales de alimentos",d:"Etiquetado, registro de instalaciones para fabricantes y procesadores, y reglas de seguridad. Los restaurantes y la venta de alimentos al público se regulan mayormente a nivel local."},
  "OSHA small business help":{who:"Seguridad en el trabajo",d:"Consultas de seguridad gratuitas y confidenciales en su lugar de trabajo que no generan multas, además de recursos de capacitación."},
  "FMCSA registration":{who:"Reglas federales para transportistas",d:"Averigüe si necesita un número USDOT o autoridad operativa para sus vehículos y rutas."},
  "Childcare.gov state resources":{who:"Departamento de Salud y Servicios Humanos de EE. UU.",d:"Enlaces a la agencia de licencias de cuidado infantil de su estado, sus reglamentos y reglas de verificación de antecedentes."},
  "U.S. Copyright Office":{who:"Proteja su trabajo creativo y su código",d:"Registre derechos de autor de arte, textos, música, fotos y software. El registro es necesario antes de demandar por infracción."},
  "SAM.gov":{who:"Vender al gobierno",d:"Registro gratuito para ofertar en contratos federales. Su SBDC o un APEX Accelerator puede ayudarle a encontrar contratos adecuados. Nunca le pague a un sitio por registrarse."},
  "Oklahoma Commercialization Network (OCN)":{who:"Puerta de entrada estatal para startups de tecnología",d:"Conecta a fundadores de tecnología y de alto crecimiento con mentoría, espacios de trabajo, preparación de presentaciones, inversionistas y apoyo para comercializar.",tip:"Pida que lo refieran a un programa adecuado para un negocio sin ingresos y con recursos propios. Confirme las tarifas y si las solicitudes están abiertas."},
  "i2E — Innovation to Enterprise":{who:"Organización sin fines de lucro para negocios escalables con base tecnológica",d:"Apoyo en etapa temprana, validación con clientes y mercado, preparación de presentaciones y contactos con el socio de OCN o la vía de financiamiento adecuada."},
  "OCAST":{who:"Oklahoma Center for the Advancement of Science and Technology",d:"Fondos estatales para comercializar tecnología, incluido el Industry Innovation Program y capital semilla. Dirigido a innovación técnica real, no a costos de registro comunes.",tip:"Vale la pena preguntar si su producto tiene un enfoque técnico novedoso, propiedad intelectual defendible o un componente de investigación. Las reglas de contrapartida varían."},
  "Oklahoma SBDC":{who:"Asesoría estatal para pequeños negocios",d:"Asesoría individual gratuita para negocios antes de abrir: evaluación de la idea, plan de negocio, presupuesto, registro y opciones de financiamiento."},
  "Oklahoma Secretary of State":{who:"Donde se registra una LLC de Oklahoma",d:"Articles of Organization (artículos de organización): $100; certificado anual: $25. Confirme el total actual antes de presentar."},
  "Oklahoma Tax Commission":{who:"Registro de impuestos estatales",d:"Averigüe qué registros de impuestos estatales le aplican. Vender productos gravables requiere un permiso de impuesto sobre ventas."},
  "Legal Aid Services of Oklahoma":{who:"Ayuda legal civil para residentes de bajos ingresos que califiquen",d:"Por lo general no es derecho comercial, pero pregunte si su caso califica o pida una referencia pro bono."},
  "Build in Tulsa":{who:"Programas para fundadores y aceleradoras selectivas",d:"Programas para empresas de tecnología o con base tecnológica. ARCH es una aceleradora presencial de 12 semanas para empresas de salud digital, energía, aeroespacial y manufactura avanzada con ingresos iniciales, y ha anunciado $70,000 en fondos no dilutivos para participantes seleccionados.",tip:"Otros grupos de 2026 ya cerraron, así que pregunte por el próximo si ARCH no le conviene."},
  "Gradient Innovation Hub":{who:"Comunidad de fundadores en el Tulsa Arts District",d:"Conozca a otros fundadores, encuentre talleres y mentores, y sepa qué programas locales están activos. Pregunte por eventos gratuitos, becas o apoyo sin costo antes de pagar por un espacio de trabajo."},
  "Tulsa Innovation Labs":{who:"Desarrollo del sector tecnológico de Tulsa",d:"No es un programa de subvenciones directas, pero es útil para redes de la industria, eventos y referencias en los sectores tecnológicos estratégicos de Tulsa."},
  "Avanzando Juntos":{who:"Organización sin fines de lucro de Tulsa que apoya a emprendedores",d:"Pregunte por microsubvenciones actuales, capital inicial, mentoría y ayuda para formalizar o registrar un negocio."},
  "SCORE Tulsa":{who:"Mentores voluntarios locales",d:"Mentoría gratuita sobre modelo de negocio, precios, investigación de clientes, mercadeo y proyecciones."},
  "TEDC / Creative Capital":{who:"Tulsa Economic Development Corporation",d:"Programas de préstamos para negocios. Pregunte si una startup sin ingresos ni garantía puede calificar, y evite un préstamo que no pueda pagar de forma realista."},
  "Greenwood Women's Business Center":{who:"Women's Business Center de la SBA en el distrito de Greenwood en Tulsa",d:"La SBA lo anunció en 2021 para atender a mujeres emprendedoras en el área metropolitana de Tulsa; lo opera U.S. Black Chambers Inc. junto con la Greenwood Chamber of Commerce. Use el localizador de la SBA para obtener los datos de contacto actuales."},
  "Partner Tulsa":{who:"Desarrollo económico y referencias de capital",d:"Referencias locales de acceso a capital. Pregunte qué programas están abiertos a un negocio antes de abrir y cuándo abren las convocatorias."},
  "Tulsa City-County Library":{who:"Centro de investigación para negocios",d:"Bases de datos gratuitas de investigación de mercado, guías para empezar e información de negocios."},
  "TU College of Law clinics":{who:"University of Tulsa",d:"Pregunte si alguna clínica actual atiende la formación de startups, acuerdos operativos o preguntas sobre contratos. Los periodos de admisión varían."},
  "Tulsa County Bar Lawyer Referral":{who:"Consulta de bajo costo",d:"Ha anunciado una consulta de 30 minutos con un abogado por $25. Confirme la tarifa actual."},
  "North Texas SBDC Network":{who:"Con sede en Dallas College · centros locales en todo el norte de Texas",d:"Asesoría, talleres y ayuda con financiamiento para quienes empiezan o hacen crecer un negocio, a través de centros locales con sede en colegios de la zona. Encuentre el centro que atiende su condado.",tip:"¿Fuera del norte de Texas? Otras regiones tienen sus propias redes de SBDC; use “Encuentre su SBDC” en En todo EE. UU."},
  "Texas Secretary of State":{who:"Donde se registra una LLC o corporación de Texas",d:"Una LLC presenta un Certificate of Formation (certificado de formación, Form 205); la tarifa es de $300. Las entidades registran aquí sus assumed names (nombres supuestos, $25 cada uno); los sole proprietors los registran ante el secretario del condado (county clerk).",tip:"El registro en línea está pasando de SOSDirect al nuevo SOSPortal. Los pagos con tarjeta agregan un pequeño cargo por conveniencia."},
  "Texas Comptroller of Public Accounts":{who:"Permiso de impuesto sobre ventas e impuesto de franquicia",d:"Obtenga un sales and use tax permit (permiso de impuesto sobre ventas y uso) si vende o arrienda bienes tangibles o vende servicios gravables en Texas. Toda LLC y corporación presenta cada año antes del 15 de mayo: en o por debajo del umbral sin impuesto a pagar ($2.65 millones para los informes de 2026 y 2027), solo el Public Information Report u Ownership Information Report, porque el No Tax Due Report ya no se presenta; por encima de él, el informe del franchise tax (impuesto de franquicia)."},
  "Texas Workforce Commission":{who:"Registro de empleadores e impuesto de desempleo",d:"Los empleadores deben registrarse con la TWC dentro de 10 días de quedar sujetos al impuesto estatal de desempleo. La mayoría se registra en línea por Unemployment Tax Registration (UTR)."},
  "Governor's Office of Small Business Assistance":{who:"Junto con la Texas Business Permit Office",d:"Ayuda con permisos estatales, licencias y cumplimiento de normas, referencias a recursos para pequeños negocios, y seminarios web y eventos gratuitos.",tip:"Use el formulario de contacto de la página para comunicarse con el equipo de Small Business Assistance."},
  "Texas Department of Licensing and Regulation":{who:"Licencias ocupacionales estatales",d:"Otorga licencias a muchas ocupaciones, entre ellas electricistas, contratistas de aire acondicionado y refrigeración, cosmetología, barbería y masoterapia. Verifique si su trabajo necesita una licencia de TDLR antes de aceptar trabajos pagados."},
  "Texas Department of State Health Services":{who:"Seguridad alimentaria y reglas de cottage food",d:"Explica las reglas de cottage food (alimentos caseros) en Texas: los negocios en casa pueden vender ciertos alimentos, el límite de ingresos brutos anuales es de $150,000 y quienes venden alimentos que requieren control de tiempo y temperatura (TCS) deben registrarse. Los restaurantes y food trucks suelen obtener permisos del departamento de salud de la ciudad o el condado."},
  "Texas Alcoholic Beverage Commission":{who:"Licencias y permisos de alcohol",d:"Vender, servir o producir alcohol en Texas requiere una licencia o permiso de la TABC. Empiece aquí antes de firmar el arrendamiento de un bar, restaurante o cervecería."},
  "Texas HHS Child Care Regulation":{who:"Licencias de cuidado infantil",d:"Otorga licencias y registros a centros y hogares de cuidado infantil. Usted elige el tipo de operación, asiste a una orientación y presenta la solicitud; primero verifique si aplica una exención."},
  "LiftFund":{who:"Prestamista sin fines de lucro para pequeños negocios",d:"Presta a negocios nuevos y existentes en Texas y otros estados, incluidos préstamos SBA Community Advantage. Los préstamos deben pagarse; pregunte por los requisitos antes de solicitar."},
  "Texas Mezzanine Fund":{who:"CDFI estatal con sede en Dallas",d:"Una community development financial institution (CDFI, institución financiera de desarrollo comunitario) que ofrece préstamos comerciales en todo Texas, con enfoque en comunidades desatendidas. Suele convenir cuando ya tiene ingresos y un plan de crecimiento."},
  "TexasLawHelp.org":{who:"Información legal gratuita para tejanos",d:"Guías y formularios legales gratuitos, y una herramienta para encontrar ayuda legal local. Por lo general no es derecho comercial, pero sirve para encontrar ayuda para la que califica."},
  "Dallas Metropolitan SBDC":{who:"Con sede en Dallas College · condados de Dallas, Collin y Rockwall",d:"Asesoría individual confidencial y sin costo para negocios nuevos y existentes, además de capacitación en temas de negocios.",tip:"El sitio web del centro tiene una sección en español."},
  "Tarrant SBDC":{who:"Con sede en Tarrant County College · condado de Tarrant, incluido Arlington",d:"Asesoría de negocios sin costo para el condado de Tarrant, parte de la North Texas SBDC Network."},
  "SCORE Dallas":{who:"Mentores voluntarios locales",d:"Mentoría gratuita de dueños de negocios y ejecutivos con experiencia, durante toda la vida de su negocio. Algunos talleres pueden cobrar una pequeña tarifa."},
  "City of Dallas Office of Economic Development":{who:"Ayuda de la Ciudad para pequeños negocios",d:"El personal le ayuda con los trámites de la Ciudad de Dallas para abrir un negocio, revisa si los programas de fondos de la Ciudad le convienen y lo conecta con recursos. El Small Business Assistance Program da subvenciones reembolsables para proyectos de bienes raíces y mejoras de capital (costo mínimo del proyecto de $150,000 en Target Areas o de $250,000 fuera de ellas, sin contar la compra o el arrendamiento de la propiedad; 75% del costo del proyecto comprometido de fuentes que no sean la Ciudad; 20 empleados o menos), así que rara vez conviene a un negocio que aún no abre.",tip:"Permisos de construcción y certificados de ocupación: Planning and Development Department, Oak Cliff Municipal Center, 320 E. Jefferson, Dallas, 214-948-4480. La Ciudad también publica la solicitud del programa en español."},
  "Dallas Public Library":{who:"Recursos de Business & Entrepreneurship (negocios y emprendimiento)",d:"Bases de datos de negocios con inicio de sesión de la biblioteca, incluida la colección de emprendimiento de Gale con planes de negocio de ejemplo y Reference Solutions para encontrar clientes. El Patent and Trademark Resource Center de la Central Library ofrece ayuda gratuita para buscar patentes y marcas."},
  "Business & Community Lenders of Texas":{who:"Prestamista sin fines de lucro con oficina en Dallas",d:"Ofrece una consulta sin costo sobre las metas de su negocio y préstamos para negocios en crecimiento en todo Texas. Los préstamos deben pagarse."},
  "Greater Dallas Hispanic Chamber of Commerce":{who:"Cámara fundada en 1939",d:"Defensa, educación y conexiones para dueños de negocios hispanos y pequeños negocios de todo origen en el norte de Texas, incluidas oportunidades de licitación y un directorio de negocios."},
  "Dallas Black Chamber of Commerce":{who:"Cámara para negocios de dueños afroamericanos",d:"Defensa, capacitación empresarial y acceso a financiamiento para negocios de dueños afroamericanos, incluidos programas de subvenciones con socios."},
  "Dallas Regional Chamber":{who:"Cámara de comercio regional",d:"Eventos, programas de liderazgo y desarrollo económico en toda la región de Dallas. Ha anunciado sesiones individuales gratuitas de AI Office Hours para negocios."},
  "Legal Aid of NorthWest Texas":{who:"Ayuda legal civil para residentes de bajos ingresos que califiquen",d:"Servicios legales civiles gratuitos en 114 condados del norte y oeste de Texas. Por lo general no es derecho comercial, pero pregunte si su caso califica."}
};
