  trades:[["Google Business Profile y Local Services Ads","Google verifica y distingue a proveedores elegibles en muchos oficios."],["Nextdoor","Los vecinos recomiendan contratistas todo el tiempo."],["Letreros en jardines y vehículos rotulados","Cada obra anuncia la siguiente (revise las reglas de letreros)."],["Agentes inmobiliarios y administradores de propiedades","Necesitan oficios confiables cada semana."],["Fotos de antes y después","Muestre su trabajo con permiso del dueño de la casa."],["Agradecimientos por referencias","Premie a los clientes que le envían trabajos."]],
  home:[["Nextdoor y grupos de vecinos","Donde la gente pide personal de limpieza y jardinería."],["Google Business Profile","Esencial para búsquedas “cerca de mí”."],["Volantes en puertas en una zona reducida","Concentrar rutas ahorra tiempo de manejo. Revise las reglas locales sobre volanteo."],["Planes de servicio recurrente","Los planes semanales o quincenales dan ingresos predecibles."],["Agentes inmobiliarios y administradores de propiedades","Limpiezas de mudanza, cambios de inquilino y trabajo de jardín."],["Premios por referencia","Un servicio gratis por cada referencia que contrate."]],
  care:[["Reservas en línea","Permita reservar al instante desde su perfil y su sitio web."],["Instagram","Trabajo de antes y después, con consentimiento escrito del cliente."],["Ofertas de introducción","Una primera visita o clase con descuento reduce la barrera."],["Alianzas","Gimnasios, salones, clínicas y negocios de bienestar pueden referirse entre sí."],["Reseñas en Google","Pídalas después de una gran visita."],["Clases comunitarias","Talleres o eventos gratuitos para conocer nuevos clientes."]],
